# Fresh integration and the fifteen finite-matrix tests in Proposition 4.21.
# The only intermediate input is the box certificate generated by this run.
include("Setup.jl")
include("Files.jl")
using TOML
include("clean_matrix_geometry.jl")
include("clean_matrix_vector.jl")
include("clean_matrix_scalar.jl")

clean_finite(x) = isguaranteed(x) && !isempty_interval(x) && isfinite(inf(x)) && isfinite(sup(x))
clean_sha(path) = open(io -> bytes2hex(sha256(io)), path)
const MATRIX_IO = ReentrantLock()
const FACTORS_DIGEST = "5b3f70f66a57ce1ad934fe1b9bdf5a8a0130d4dbe19f9cb6b2034af4d309801b"
const PILOT_COLUMNS = (32, 215, 324)
const TABLE4_ROWS = vcat(["$(p)_T$(t)U$(u)" for p in ("odd","even") for t in 0:2 for u in 0:1],
                         ["scalar_S0V0","scalar_S1V0","scalar_S2V1"])

function clean_matrix_factors(rows)
    file = joinpath(PROOF_DATA, "Coercivity", "selected_factors.tsv")
    clean_sha(file) == FACTORS_DIGEST || error("changed selective factors")
    lines = readlines(file)
    split(first(lines),'\t') == ["row","direction","q","name","threshold_lower","threshold_upper",
        "nu_upper","scale_milli","margin_lower"] || error("unrecognized factor file")
    factors = Dict{String,Rational{Int}}()
    index = 0
    for row in rows
        row.block == :odd || continue
        for (i,f) in enumerate(row.fs)
            index += 1
            fields = split(lines[index+1],'\t')
            length(fields)==9 && fields[1]==row.id && parse(Int,fields[2])==i &&
                parse(Int,fields[3])==index && fields[4]==f.name && !haskey(factors,f.name) ||
                error("factor assigned to the wrong functional")
            factors[f.name] = parse(Int,fields[8]) // 1000
        end
    end
    length(lines)==27 && index==26 || error("incomplete factor assignment")
    return factors
end

# The effective weights are fixed input data for both Table 2 and Table 4.
# Reconstruct their mathematical definitions here as an independent identity check.
function clean_source_weights(rows)
    factors=clean_matrix_factors(rows)
    path=joinpath(PROOF_DATA,"Coercivity","Fixed_weighted_responses.jld2")
    weights=Dict{String,Interval{Float64}}()
    jldopen(path,"r") do file
        file["schema"]=="clean-exact-spline-coefficients-v1" &&
            file["factors_sha256"]==FACTORS_DIGEST || error("unrecognized fixed response data")
        for group in ("odd","even")
            fs=[f for row in rows if (row.block==:odd)==(group=="odd") for f in row.fs]
            names=file[group*"_names"]
            stored=vec(file[group*"_nu"])
            names==[f.name for f in fs] && length(stored)==length(fs) || error("fixed weight order mismatch")
            for (f,value) in zip(fs,stored)
                s=get(factors,f.name,1//1)
                expected=interval(Float64,f.nu)*interval(Float64,s)^2
                actual=interval(Float64,value)
                isequal_interval(expected,actual) && clean_finite(actual) && inf(actual)>0 ||
                    error("the fixed matrix weight for $(f.name) differs from its definition")
                weights[f.name]=actual
            end
        end
    end
    length(weights)==58 || error("incomplete fixed functional weights")
    return weights
end

# Use the original physical support with every profile knot and spectral basis boundary.
# Where the odd step field enters, retain every radial jump. On odd_T1U0 two
# active step heights per radial bin suffice to split the axial support.
function clean_geometry(inputs,boxes,row)
    br,bz = (inputs.coercivity.bases[s] for s in (row.r_basis,row.z_basis))
    radial_steps = row.block==:odd && row.id!="odd_T0U1"
    ub = matrix_grid(inputs.profile.U,first(br.nodes),last(br.nodes),br.nodes,
                     radial_steps ? boxes.U : ())
    vb = matrix_grid(inputs.profile.V,max(big(I"0"),first(bz.nodes)),last(bz.nodes),bz.nodes,
                     radial_steps && row.id!="odd_T1U0" ? boxes.V : ())
    full_radial = row.id in ("odd_T0U0","odd_T0U1","odd_T1U0","even_T0U1")
    radial = full_radial ? strip_axis_plan(ub,br.nodes) : row_axial_plan(ub,br.nodes)
    # One checkpoint for each native radial parent. Recheck all its subdivisions.
    axial = row_axial_plan(vb,bz.nodes).refined
    axes_for_strip = fill(axial,length(ub)-1)
    if row.id=="odd_T1U0"
        for i in eachindex(axes_for_strip)
            bin = searchsortedlast(inf.(boxes.U),inf(ub[i]))
            1<=bin<=length(boxes.columns) && sup(ub[i+1])<=sup(boxes.U[bin+1]) ||
                error("odd_T1U0 radial parent crosses a step")
            q = boxes.columns[bin]
            cuts = copy(vb)
            for j in (q.j1,q.j2)
                j==0 && continue
                v=boxes.V[j+1]
                inf(first(vb))<inf(v)<inf(last(vb)) && push!(cuts,v)
            end
            cuts=interval.(BigFloat,sort!(unique!(inf.(cuts))))
            axes_for_strip[i]=row_axial_plan(strip_checked_points(vb,cuts),bz.nodes).refined
        end
    elseif row.id=="odd_T0U0"
        # The three pilot parents used the finer axial plan on every subinterval.
        for i in PILOT_COLUMNS
            axes_for_strip[i]=strip_axis_plan(vb,bz.nodes).refined
        end
    elseif row.id in ("odd_T0U1","even_T0U1")
        z = zeta_bound(boxes,(first(ub),last(ub),first(vb),last(vb)))
        clean_finite(z) && isthinzero(z) || error("step potential must vanish on T0U1")
    end
    return (;row,U=ub,base_V=vb,radial=radial.partitions,axial=axes_for_strip,K=length(gram_modes(row)))
end

function matrix_run_id()
    run_id=ENV["CLEAN_RUN_ID"]
    !isempty(run_id) || error("missing clean run identifier")
    return run_id
end

function clean_matrix_identity(boxfile)
    src=join(sort!([string(k,'=',v) for (k,v) in proof_signature()]),"\n")
    # Include the numerical libraries and the fresh signed box container.
    return bytes2hex(sha256(join(("clean-matrix-v1",matrix_run_id(),src,clean_sha(boxfile),
        FACTORS_DIGEST,clean_sha(joinpath(PROOF_DATA,"Coercivity","Fixed_weighted_responses.jld2")),string(VERSION),string(pkgversion(IntervalArithmetic)),string(pkgversion(JLD2))),"\n")))
end

function clean_matrix_inputs()
    boxfile=joinpath(OUTPUT,"Boxes.jld2")
    rec=read_proof(boxfile)
    rec["signature"]==proof_signature() && isnothing(get(rec,"legacy_checkpoint_provenance",nothing)) ||
        error("fresh matrix integration requires the current box proof")
    boxes=rec["boxes"]
    length(boxes.columns)==2482 || error("incomplete box input")
    inputs=load_proof_inputs()
    [r.id for r in inputs.coercivity.rows]==TABLE4_ROWS || error("unexpected Table 4 row order")
    return inputs,boxes,clean_matrix_identity(boxfile)
end

# One vertical moment table per distinct interval and integration order. Local
# basis changes and the step-potential partition depend on the radial parent.
function matrix_orders(ctx,i)
    id=ctx.row.id
    if id=="odd_T0U0" || id=="odd_T2U1"
        return (12,)
    elseif id=="odd_T1U0" && (i in 1:11 || i in 179:190)
        return (6,12)
    elseif id in ("odd_T0U1","even_T0U1")
        return (6,12)
    else
        return (6,)
    end
end

function prepare_moments(inputs,ctx,pending)
    row=ctx.row
    mr=sort!(unique(m for (m,_,_) in gram_modes(row)))
    mz=sort!(unique(k for (_,k,_) in gram_modes(row)))
    effective = row.block==:even ? merge(row,(η=row.η-(I"0.235059685902438"-I"0.224"),)) : row
    ctx6=(row=effective,U=ctx.U)
    # Spline pieces over coincident intervals have identical moments regardless of parent.
    cache6=Dict();cache12=Dict();cache_scalar=Dict()
    tables=Dict()
    for i in pending
        v=ctx.axial[i]
        for degree in (row.s==1 ? (8,) : matrix_orders(ctx,i))
            key=(Tuple(inf.(v)),degree)
            haskey(tables,key) && continue
            if degree==8
                tables[key]=[get!(cache_scalar,(inf(v[j]),inf(v[j+1]))) do
                    axial_data(inputs,row,ctx.U[1],ctx.U[2],v[j],v[j+1],mz)
                end for j in 1:length(v)-1]
            elseif degree==6
                tables[key]=[axial_moments(inputs,ctx6,cache6,v[j],v[j+1]) for j in 1:length(v)-1]
            else
                tables[key]=[axial_moments12(inputs,ctx,cache12,v[j],v[j+1]) for j in 1:length(v)-1]
            end
        end
    end
    return (;tables,mr,effective)
end

# On an odd, step-dependent parent the geometry retains every radial jump. Pass
# the unique overlapping column to the original zeta_bound; check every active
# axial jump is on the mesh before using the constant height on a rectangle.
function local_step_box(boxes,ctx,i)
    a,b=first(ctx.radial[i]),last(ctx.radial[i])
    bin=searchsortedlast(boxes.U,a;by=inf)
    1<=bin<=length(boxes.columns) && sup(b)<=sup(boxes.U[bin+1]) ||
        error("matrix radial strip crosses or lies outside the box partition")
    v=ctx.axial[i]
    q=boxes.columns[bin]
    for j in (q.j1,q.j2)
        j==0 && continue
        edge=boxes.V[j+1]
        if inf(first(v)) < inf(edge) < inf(last(v))
            pos=searchsortedfirst(v,edge;by=inf)
            isequal_interval(v[pos],edge) || error("matrix axial strip crosses a step")
        end
    end
    return (U=boxes.U[bin:bin+1],V=boxes.V,columns=[q])
end

function matrix_strip(inputs,boxes,ctx,i,moments)
    row=ctx.row
    u,v=ctx.radial[i],ctx.axial[i]
    G=fill(I"0",ctx.K,ctx.K); G2=copy(G)
    stepbox=(row.block==:odd && row.id!="odd_T0U1") ? local_step_box(boxes,ctx,i) : nothing
    heights=isnothing(stepbox) ? fill(I"0",length(v)-1) :
        [zeta_bound(stepbox,(first(u),last(u),v[j],v[j+1])) for j in 1:length(v)-1]
    # Each Taylor polynomial is integrated inside a single spline piece; the
    # step field is constant on each child rectangle. The two rigorous orders
    # may be intersected because their domains and integrands agree.
    for k in 1:length(u)-1
        a,b=u[k],u[k+1]
        if row.s==1
            vertical=moments.tables[(Tuple(inf.(v)),8)]
            g,g2=scalar_column(inputs,row,a,b,v,vertical,moments.mr,i in (1,length(ctx.radial)÷2,length(ctx.radial)))
        else
            g=g2=nothing
            for degree in matrix_orders(ctx,i)
                vert=moments.tables[(Tuple(inf.(v)),degree)]
                gx,gx2=degree==6 ? grams_child(inputs,moments.effective,a,b,v,vert,heights) :
                                   grams_child12(inputs,row,a,b,v,vert,heights)
                g=isnothing(g) ? gx : intersect_interval.(g,gx)
                g2=isnothing(g2) ? gx2 : intersect_interval.(g2,gx2)
            end
        end
        G.+=strip_validate_matrix(g,ctx.K)
        G2.+=strip_validate_matrix(g2,ctx.K)
    end
    if row.id=="odd_T0U0"
        # Independent, original full-parent integral, recomputed in this run.
        native=gram_column(inputs.profile,row,inputs.coercivity.bases,stepbox,inputs.far,ctx.U,ctx.base_V,i)
        G=strip_validate_matrix(intersect_interval.(G,native.G),ctx.K)
        G2=strip_validate_matrix(intersect_interval.(G2,native.G2),ctx.K)
    end
    return G,G2
end

matrix_pack(A)=[A[i,j] for j in axes(A,2) for i in 1:j]
function matrix_unpack(values,K)
    values isa Vector{Interval{Float64}} && length(values)==K*(K+1)÷2 &&
        all(clean_finite,values) || error("invalid packed interval matrix")
    A=Matrix{Interval{Float64}}(undef,K,K)
    k=0
    for j in 1:K,i in 1:j
        k+=1
        A[i,j]=A[j,i]=values[k]
    end
    return A
end

function strip_checksum(G,G2)
    h=SHA.SHA2_256_CTX()
    for vals in (G,G2), endpt in (inf,sup)
        SHA.update!(h,reinterpret(UInt8,endpt.(vals)))
    end
    return bytes2hex(SHA.digest!(h))
end
strip_path(row,i)=joinpath(OUTPUT,"clean_matrix_blocks",row.id,"strip_$i.jld2")
function load_strip(ctx,i,identity)
    file=strip_path(ctx.row,i)
    d=JLD2.load(file)
    d["identity"]==identity && d["run_id"]==matrix_run_id() && d["row"]==ctx.row.id && d["index"]==i &&
        d["method"]=="fresh_taylor_gram_v1" &&
        all(isequal_interval.(d["u"],ctx.radial[i])) && all(isequal_interval.(d["v"],ctx.axial[i])) ||
        error("strip identity, method, or geometry mismatch in $file")
    g,g2=d["G"],d["G2"]
    d["checksum"]==strip_checksum(g,g2) || error("strip payload checksum mismatch in $file")
    return matrix_unpack(g,ctx.K),matrix_unpack(g2,ctx.K)
end

function publish_strip(ctx,i,identity,G,G2)
    path=strip_path(ctx.row,i)
    g,g2=matrix_pack(G),matrix_pack(G2)
    lock(MATRIX_IO) do
        dir=mkpath(dirname(path))
        tmp,io=mktemp(dir);close(io)
        try
            jldsave(tmp,true;identity,run_id=matrix_run_id(),row=ctx.row.id,index=i,method="fresh_taylor_gram_v1",
                    u=ctx.radial[i],v=ctx.axial[i],checksum=strip_checksum(g,g2),G=g,G2=g2)
            try
                hardlink(tmp,path)
            catch
                isfile(path) || rethrow()
                load_strip(ctx,i,identity)
            end
        finally
            rm(tmp;force=true)
        end
    end
end

function work_matrix(inputs,boxes,identity,row_index,lane,lanes,deadline)
    1<=lane<=lanes && 1<=row_index<=15 || error("invalid matrix assignment")
    ctx=clean_geometry(inputs,boxes,inputs.coercivity.rows[row_index])
    pending=Int[]
    for i in lane:lanes:length(ctx.radial)
        if isfile(strip_path(ctx.row,i))
            load_strip(ctx,i,identity)
        else
            push!(pending,i)
        end
    end
    isempty(pending) && return true
    time()>=deadline && return false
    println(ctx.row.id," lane ",lane,"/",lanes,", ",length(pending)," fresh radial strips");flush(stdout)
    moments=prepare_moments(inputs,ctx,pending)
    Threads.@threads :dynamic for k in eachindex(pending)
        if time()<deadline
            i=pending[k]
            G,G2=matrix_strip(inputs,boxes,ctx,i,moments)
            publish_strip(ctx,i,identity,G,G2)
            println(ctx.row.id," saved strip ",i,"/",length(ctx.radial));flush(stdout)
        end
    end
    return all(i->isfile(strip_path(ctx.row,i)),pending)
end

function assemble_clean_row(inputs,boxes,identity,row,weights)
    ctx=clean_geometry(inputs,boxes,row)
    G=fill(I"0",ctx.K,ctx.K);G2=copy(G)
    nr=length(ctx.radial)
    ledger=Vector{String}(undef,nr)
    rectangles=0
    for i in 1:nr
        g,g2=load_strip(ctx,i,identity)
        G.+=g;G2.+=g2
        rectangles+=(length(ctx.radial[i])-1)*(length(ctx.axial[i])-1)
        ledger[i]=clean_sha(strip_path(row,i))
    end
    gap=verify_complement_gap(row,inputs.coercivity.bases)
    br,bz=(inputs.coercivity.bases[s] for s in (row.r_basis,row.z_basis))
    λ=[gram_eigenvalue(br,m)+gram_eigenvalue(bz,k) for (m,k,component) in gram_modes(row)]
    N=assemble_N(row.d,λ,G,G2,row.Λstar,row.W)
    basis=complete_coercivity_design(row,N)
    basis.L==collect(1:row.n) || error("changed functional ordering in $(row.id)")
    ν=Interval{Float64}[]
    for (p,l) in enumerate(basis.L)
        f=row.fs[p]
        all(isequal_interval.(basis.X[:,l],interval.(Float64,vcat(f.xi1,f.xi2)))) ||
            error("functional direction changed in $(row.id)")
        isequal_interval(basis.nu[p],interval(Float64,f.nu)) || error("changed baseline weight")
        push!(ν,weights[f.name])
    end
    design=(X=basis.X,L=basis.L,nu=ν)
    certificate=certify_matrix(N,design.X,design.L,design.nu,row.η)
    margins=[g+(j<=row.n ? ν[j] : I"0") for (j,g) in enumerate(certificate.g)]
    minimum(inf.(margins))>=0 && sup(certificate.epsilon)<=inf(interval(Float64,9//10^11)) ||
        error("matrix margins or the manuscript's uniform loss failed in $(row.id)")
    file=joinpath(OUTPUT,"matrices",row.id*".jld2")
    save_proof(file;row_id=row.id,G,G2,Λ=λ,N,design,certificate,gap,margins,
               strip_sha256=ledger,radial_parents=nr,rectangles,identity)
    return Dict("verified"=>true,"directions"=>ctx.K,"selected"=>row.n,"radial_parents"=>nr,
        "rectangles"=>rectangles,"minimum_margin_lower"=>minimum(inf.(margins)),
        "norm_upper"=>sup(certificate.normN),"loss_upper"=>sup(certificate.epsilon),
        "orthogonality_upper"=>sup(certificate.tau),"complementary_gap_lower"=>inf(gap),
        "result_sha256"=>clean_sha(file),"file"=>relpath(file,OUTPUT))
end

function assemble_clean_matrices(inputs,boxes,identity)
    rows=inputs.coercivity.rows
    weights=clean_source_weights(rows)
    summaries=Dict{String,Any}()
    for row in rows
        summaries[row.id]=assemble_clean_row(inputs,boxes,identity,row,weights)
        println(row.id," verified; minimum margin >= ",summaries[row.id]["minimum_margin_lower"])
        flush(stdout)
    end
    length(summaries)==15 && sum(r.n for r in rows if r.block==:odd)==26 &&
        sum(r.n for r in rows if r.block!=:odd)==32 || error("incomplete matrix inventory")
    summary=Dict("format"=>"clean_table4_v1","identity"=>identity,"run_id"=>matrix_run_id(),"all_checks_passed"=>true,
                 "matrix_count"=>15,"selected_odd"=>26,"selected_even"=>32,"rows"=>summaries)
    mktemp(OUTPUT) do temp,io
        TOML.print(io,summary;sorted=true);close(io)
        mv(temp,joinpath(OUTPUT,"table4_checks.toml");force=true)
    end
    return summary
end

function matrix_main(args)
    deadline=proof_deadline()
    inputs,boxes,identity=clean_matrix_inputs()
    if length(args)==4 && args[1]=="work"
        return work_matrix(inputs,boxes,identity,parse.(Int,args[2:end])...,deadline) ? 0 : 75
    elseif args==["assemble"]
        assemble_clean_matrices(inputs,boxes,identity)
        return 0
    end
    error("usage: clean_matrices.jl work ROW_INDEX LANE LANES | assemble")
end
abspath(PROGRAM_FILE)==(@__FILE__) && exit(matrix_main(ARGS))
